// Package argparse is a minimal command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, short, usage string
	b                  *bool   // set for boolean flags
	s                  *string // set for value flags
}

type argDef struct {
	name, usage string
	s           *string
}

type Parser struct {
	name, desc string
	flags      []*flagDef
	args       []*argDef
	rest       []string
}

func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc}
}

// Bool defines a boolean flag. short may be empty.
func (p *Parser) Bool(name, short, usage string) *bool {
	b := new(bool)
	p.flags = append(p.flags, &flagDef{name: name, short: short, usage: usage, b: b})
	return b
}

// String defines a flag that takes a value. short may be empty.
func (p *Parser) String(name, short, def, usage string) *string {
	s := &def
	p.flags = append(p.flags, &flagDef{name: name, short: short, usage: usage, s: s})
	return s
}

// Arg defines a required positional argument. Arguments are filled in
// definition order.
func (p *Parser) Arg(name, usage string) *string {
	s := new(string)
	p.args = append(p.args, &argDef{name: name, usage: usage, s: s})
	return s
}

// Rest returns the positional arguments left over after the defined ones.
func (p *Parser) Rest() []string { return p.rest }

func (p *Parser) lookup(name string, long bool) *flagDef {
	for _, f := range p.flags {
		if long && f.name == name || !long && f.short == name {
			return f
		}
	}
	return nil
}

// Parse parses args, which should not include the program name.
// Accepted forms: --name, --name=value, --name value, -n, -n=value, -n value.
// Everything after "--" is positional.
func (p *Parser) Parse(args []string) error {
	var pos []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			pos = append(pos, args[i+1:]...)
			break
		}
		if len(a) < 2 || a[0] != '-' {
			pos = append(pos, a)
			continue
		}

		arg, val, hasVal := strings.Cut(a, "=")
		long := strings.HasPrefix(arg, "--")
		name := strings.TrimPrefix(arg[1:], "-")
		f := p.lookup(name, long)
		if f == nil {
			if arg == "--help" || arg == "-h" {
				return ErrHelp
			}
			return fmt.Errorf("unknown flag: %s", arg)
		}

		if f.b != nil {
			*f.b = true
			if hasVal {
				v, err := strconv.ParseBool(val)
				if err != nil {
					return fmt.Errorf("invalid boolean for %s: %q", arg, val)
				}
				*f.b = v
			}
			continue
		}
		if !hasVal {
			if i++; i >= len(args) {
				return fmt.Errorf("flag %s needs a value", arg)
			}
			val = args[i]
		}
		*f.s = val
	}

	if len(pos) < len(p.args) {
		return fmt.Errorf("missing argument: <%s>", p.args[len(pos)].name)
	}
	for i, d := range p.args {
		*d.s = pos[i]
	}
	p.rest = pos[len(p.args):]
	return nil
}

// Usage returns the help message built from the definitions.
func (p *Parser) Usage() string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "Usage: %s [flags]", p.name)
	for _, a := range p.args {
		fmt.Fprintf(&sb, " <%s>", a.name)
	}
	sb.WriteString("\n")
	if p.desc != "" {
		fmt.Fprintf(&sb, "\n%s\n", p.desc)
	}

	w := tabwriter.NewWriter(&sb, 0, 0, 2, ' ', 0)
	if len(p.args) > 0 {
		fmt.Fprintln(w, "\nArguments:")
		for _, a := range p.args {
			fmt.Fprintf(w, "  %s\t%s\n", a.name, a.usage)
		}
	}
	fmt.Fprintln(w, "\nFlags:")
	for _, f := range p.flags {
		names := "    --" + f.name
		if f.short != "" {
			names = "-" + f.short + ", --" + f.name
		}
		usage := f.usage
		if f.s != nil {
			names += " <value>"
			if *f.s != "" {
				usage += fmt.Sprintf(" (default %q)", *f.s)
			}
		}
		fmt.Fprintf(w, "  %s\t%s\n", names, usage)
	}
	fmt.Fprintln(w, "  -h, --help\tshow this help")
	w.Flush()
	return sb.String()
}

package argparse

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

func newParser() (p *Parser, verbose *bool, out, src *string) {
	p = New("cp", "Copy things.")
	verbose = p.Bool("verbose", "v", "print more")
	out = p.String("output", "o", "a.out", "output file")
	src = p.Arg("src", "source file")
	return
}

func TestParse(t *testing.T) {
	p, verbose, out, src := newParser()
	usage := p.Usage() // before Parse, so defaults are the defined ones

	err := p.Parse([]string{"-v", "in.txt", "--output=x", "extra", "--", "-notflag"})
	if err != nil {
		t.Fatal(err)
	}
	if !*verbose || *out != "x" || *src != "in.txt" {
		t.Errorf("got verbose=%v out=%q src=%q", *verbose, *out, *src)
	}
	if want := []string{"extra", "-notflag"}; !reflect.DeepEqual(p.Rest(), want) {
		t.Errorf("Rest() = %q, want %q", p.Rest(), want)
	}

	for _, want := range []string{"Usage: cp [flags] <src>", "-v, --verbose", `-o, --output <value>  output file (default "a.out")`, "source file", "-h, --help"} {
		if !strings.Contains(usage, want) {
			t.Errorf("usage missing %q:\n%s", want, usage)
		}
	}
}

func TestParseForms(t *testing.T) {
	p, verbose, out, _ := newParser()
	if err := p.Parse([]string{"-o", "y", "--verbose=false", "s"}); err != nil {
		t.Fatal(err)
	}
	if *verbose || *out != "y" {
		t.Errorf("got verbose=%v out=%q", *verbose, *out)
	}
}

func TestParseErrors(t *testing.T) {
	for _, tc := range []struct {
		args []string
		want string
	}{
		{[]string{"--nope", "s"}, "unknown flag: --nope"},
		{[]string{"s", "-o"}, "flag -o needs a value"},
		{[]string{"-v"}, "missing argument: <src>"},
		{[]string{"--verbose=maybe", "s"}, "invalid boolean"},
		{[]string{"-verbose", "s"}, "unknown flag: -verbose"},
	} {
		p, _, _, _ := newParser()
		err := p.Parse(tc.args)
		if err == nil || !strings.Contains(err.Error(), tc.want) {
			t.Errorf("Parse(%q) = %v, want %q", tc.args, err, tc.want)
		}
	}

	p, _, _, _ := newParser()
	if err := p.Parse([]string{"--help"}); !errors.Is(err, ErrHelp) {
		t.Errorf("--help: got %v, want ErrHelp", err)
	}
}

